# -*- coding: utf-8 -*-
def S(id,type,authors,year,title,container,note,**kw):
    d={"id":id,"type":type,"authors":authors,"year":year,"title":title,"container":container}
    d.update({k:v for k,v in kw.items() if k not in("po","oa")})
    d["peer_reviewed"]=kw.get("po",True); d["open_access"]=kw.get("oa",False)
    d["note"]=note; d["library"]="mendeley"
    return d
